// Read one current-chat assistant snapshot. Never inherit a user's empty cache or another chat.
const messageStateObject=value=>value&&typeof value==='object'&&!Array.isArray(value);
const messageStateValid=value=>messageStateObject(value)&&value.schema_version===1&&messageStateObject(value.world)&&messageStateObject(value.player);

function readCurrentAssistantState({context,getvar,generateType='',lastMessageId,phase='before'}={}){
  const chat=context?.chat;
  if(!Array.isArray(chat)||typeof getvar!=='function'||!['before','preprocess'].includes(phase))return {};
  let boundary=Number.isInteger(lastMessageId)?Math.min(lastMessageId,chat.length-1):chat.length-1;
  const last=chat[boundary];
  // Only native regenerate removes the last assistant between AFTER_COMMANDS and WI preprocessing.
  const replacing=['swipe','append','continue','appendFinal'].includes(generateType)||phase==='before'&&generateType==='regenerate';
  if(replacing&&last?.is_user===false&&last.is_system!==true)boundary--;
  for(let id=boundary;id>=0;id--){
    const message=chat[id];
    if(!message||message.is_user!==false||message.is_system===true)continue;
    const swipe=message.swipe_id??0;
    if(!Number.isInteger(swipe)||swipe<0)continue;
    if(!messageStateValid(message.variables?.[swipe]?.stat_data))continue;
    const value=getvar('stat_data',{scope:'message',withMsg:{id,swipe_id:swipe},defaults:null,clone:true});
    return messageStateValid(value)?value:{};
  }
  return {};
}

// Pure context selection and bounded text rendering; the build embeds this in EJS.
const scopedObject=value=>value&&typeof value==='object'&&!Array.isArray(value)?value:{};
const scopedText=(value,max=160)=>typeof value==='string'?value.trim().slice(0,max):'';
const scopedDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;
const scopedTime=value=>typeof value==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(value);
const scopedEscape=value=>String(value??'').replace(/[&<>"'{}%]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&#34;',"'":'&#39;','{':'&#123;','}':'&#125;','%':'&#37;'}[c]));
const scopedLocation=value=>{const name=scopedText(value,80),aliases={'\u65e7\u6821\u820d\u6d3b\u52a8\u5ba4':'\u65e7\u6d3b\u52a8\u5ba4','\u65e7\u6821\u820d\u8d70\u5eca':'\u65e7\u8d70\u5eca','\u516c\u544a\u680f\u524d':'\u516c\u544a\u680f','\u6821\u56ed\u4e2d\u5ead':'\u6821\u5ead','\u97f3\u4e50\u7ec3\u4e60\u5ba4A':'\u7b2c\u4e00\u7ec3\u4e60\u5ba4','\u97f3\u4e50\u7ec3\u4e60\u5ba4B':'\u7b2c\u4e8c\u7ec3\u4e60\u5ba4','\u72ec\u7acb\u94a2\u7434\u7ec3\u4e60\u5ba4\u95e8\u53e3':'\u72ec\u7acb\u94a2\u7434\u7ec3\u4e60\u5ba4','\u65e7\u6821\u820d\u00b7\u72ec\u7acb\u94a2\u7434\u7ec3\u4e60\u5ba4':'\u72ec\u7acb\u94a2\u7434\u7ec3\u4e60\u5ba4','\u7ec3\u4e60\u5ba4\u8d70\u5eca':'\u7b2c\u4e00\u7ec3\u4e60\u5ba4','\u97f3\u4e50\u5ba4\u95e8\u53e3':'\u97f3\u4e50\u5ba4','\u6587\u5b66\u793e\u6d3b\u52a8\u5ba4':'\u6587\u5b66\u6d3b\u52a8\u5ba4','\u53e4\u5178\u90e8\u6d3b\u52a8\u5ba4':'\u6587\u5b66\u6d3b\u52a8\u5ba4','\u56fe\u4e66\u9986':'\u5e02\u7acb\u56fe\u4e66\u9986','\u6559\u804c\u5458\u5ba4':'\u6559\u5e08\u529e\u516c\u5ba4','\u804c\u5458\u5ba4':'\u6559\u5e08\u529e\u516c\u5ba4','\u660e\u706f\u9910\u5385':'\u5bb6\u5ead\u9910\u5385\u00b7\u660e\u706f','\u5bb6\u5ead\u9910\u5385\u660e\u706f':'\u5bb6\u5ead\u9910\u5385\u00b7\u660e\u706f','\u53cc\u53f6\u7406\u592e\u5b9e\u9a8c\u5ba4':'\u79d1\u5b66\u6559\u5ba4','\u5b9e\u9a8c\u533a':'\u79d1\u5b66\u6559\u5ba4','\u8bb0\u5f55\u4e0e\u5c55\u793a\u533a':'\u79d1\u5b66\u6559\u5ba4','\u9ad8\u4e092\u73ed\u6559\u5ba4':'\u9ad8\u4e092\u73ed','\u5343\u53f6\u7ad9\u524d':'\u7ad9\u524d\u5e7f\u573a'};return aliases[name]??name;};

function scopedEvidence(input,catalog){
 const s=scopedObject(input),world=scopedObject(s.world),logs=scopedObject(s.event_log),events=scopedObject(s.events),facts=scopedObject(s.knowledge?.facts),characters=scopedObject(s.characters);
 const raw=scopedObject(s.player?.control),id=scopedText(raw.character_id,100),name=scopedText(raw.canonical_name,80);
 const control=raw.mode==='cast'&&catalog.canonicalActors[id]===name?{mode:'cast',character_id:id,canonical_name:name}:{mode:'custom',character_id:null,canonical_name:null};
 const own=control.canonical_name;
 const playerValue=container=>{const values=scopedObject(container);return Object.hasOwn(values,'player')?values.player:own?values[own]:undefined;};
 const location=scopedLocation(world.current_location),ready=s.schema_version===1&&scopedDate(world.current_date)&&scopedTime(world.current_time)&&!!location&&!['\u5f85\u786e\u5b9a','\u672a\u5b9a','\u672a\u786e\u8ba4'].includes(location);
 const now=ready?world.current_date+' '+world.current_time:'';
 const rawLogKnown=log=>ready&&playerValue(log?.known_by)===true&&scopedDate(log.date)&&scopedTime(log.time)&&log.date+' '+log.time<=now&&/^(chat:[^:]+:message:[^:]+|phone:[^:]+:message:[^:]+|opening:[^:]+:revision:\d+)$/.test(log.source_message_id??'');
 const mai=events.mai_visibility,maiKnown=Object.keys(scopedObject(mai?.source_log_ids)).some(id=>rawLogKnown(logs[id])&&logs[id].event_id==='mai_visibility');
 const maiForgotten=own!=='\u6a31\u5c9b\u9ebb\u8863'&&maiKnown&&!['\u5df2\u5b8c\u6210','\u5df2\u53d6\u6d88'].includes(mai?.state)&&mai?.flags?.resolved!==true&&mai?.results?.player_remembers==='\u9057\u5fd8';
 const logKnown=log=>rawLogKnown(log)&&!(maiForgotten&&(log.event_id==='mai_visibility'||/^story_H(29|30|31|32)$/.test(log.event_id??'')||log.actors?.['\u6a31\u5c9b\u9ebb\u8863']===true));
 const factKnown=(id,fact)=>{const acquisition=playerValue(fact?.known_by);return fact?.truth_status==='\u5df2\u786e\u8ba4'&&acquisition&&scopedDate(fact.date)&&fact.date<=world.current_date&&scopedDate(acquisition.date)&&acquisition.date<=world.current_date&&!!scopedText(acquisition.method)&&!!scopedText(acquisition.source)&&logKnown(logs[fact.source_log_id])&&logs[fact.source_log_id].fact_ids?.[id]===true;};
 const availableName=name=>name!==own&&!(name==='\u6a31\u5c9b\u9ebb\u8863'&&maiForgotten);
 const named=name=>availableName(name)&&characters[name]?.known===true&&!!scopedText(characters[name].display_name,40);
 const atSite=name=>ready&&availableName(name)&&characters[name]?.present===true&&!!scopedText(characters[name].location_basis)&&scopedLocation(characters[name].location)===location;
 const capability=(name,sense)=>{const c=characters[name],record=playerValue(s.knowledge?.perception?.[name]);if(!availableName(name))return false;if(name!=='\u5e9a\u5915\u5b50'&&c?.perception_mode==='\u666e\u901a'&&!(name==='\u6a31\u5c9b\u9ebb\u8863'&&record))return true;return !!record&&record[sense]===true&&!!scopedText(record.basis)&&scopedDate(record.established_date)&&record.established_date<=world.current_date&&Object.keys(scopedObject(record.source_fact_ids)).every(id=>factKnown(id,facts[id]));};
 const displayName=name=>name==='player'||name===own?'\u73a9\u5bb6':named(name)?scopedText(characters[name].display_name,40):'';
 return{s,world,characters,logs,events,facts,control,own,playerValue,location,ready,now,maiForgotten,logKnown,factKnown,named,atSite,capability,displayName};
}

function projectCampusContext(input,catalog){
 const e=scopedEvidence(input,catalog),{s,world,characters,logs,events,facts}=e;
 const onsite=Object.keys(characters).filter(name=>e.named(name)&&e.atSite(name)&&e.capability(name,'see')).sort().slice(0,6);
 const heard=Object.keys(characters).filter(name=>e.named(name)&&e.atSite(name)&&!e.capability(name,'see')&&e.capability(name,'hear')).sort().slice(0,3);
 const appointments=Object.entries(scopedObject(s.phone?.context?.appointments)).filter(([,a])=>['\u5df2\u7ea6\u5b9a','\u5df2\u6539\u671f'].includes(a.state)&&e.playerValue(a.participants)===true&&Object.keys(scopedObject(a.participants)).every(name=>(name==='player'||name===e.own?e.playerValue(a.accepted_by):a.accepted_by?.[name])===true)&&scopedDate(a.date)&&scopedTime(a.time)&&a.date===world.current_date&&Object.keys(scopedObject(a.source_log_ids)).some(id=>e.logKnown(logs[id]))).sort(([a,x],[b,y])=>x.time.localeCompare(y.time)||a.localeCompare(b)).slice(0,3).map(([id,a])=>({id,time:a.time,event_id:typeof a.event_id==='string'?a.event_id:null,location:scopedText(a.location,80),participants:[...new Set(Object.keys(scopedObject(a.participants)).map(e.displayName).filter(Boolean))]}));
 const related=Object.entries(events).filter(([id,event])=>(scopedLocation(event.location)===e.location||appointments.some(a=>a.event_id===id&&scopedLocation(a.location)===e.location))&&Object.keys(scopedObject(event.source_log_ids)).some(lid=>e.logKnown(logs[lid])&&logs[lid].event_id===id)).sort(([a],[b])=>a.localeCompare(b)).slice(0,3);
 const selectedLogs=new Set(related.flatMap(([id,event])=>Object.keys(scopedObject(event.source_log_ids)).filter(lid=>e.logKnown(logs[lid])&&logs[lid].event_id===id)));
 const knownFacts=Object.entries(facts).filter(([id,fact])=>selectedLogs.has(fact.source_log_id)&&e.factKnown(id,fact)).sort(([a],[b])=>a.localeCompare(b)).slice(0,3).map(([,fact])=>{const log=logs[fact.source_log_id],acquisition=e.playerValue(fact.known_by);return{claim:scopedText(fact.claim,140),date:log.date,time:log.time,method:scopedText(acquisition.method),source:scopedText(acquisition.source),modality:log.source_message_id.startsWith('phone:')?'\u901a\u4fe1':'\u5df2\u77e5\u7ecf\u5386'};});
 const knownEvents=related.map(([id,event])=>{const title=scopedText(event.title);const known=title&&[...selectedLogs].some(lid=>logs[lid].event_id===id&&[scopedText(logs[lid].player_action),scopedText(logs[lid].result),...Object.entries(scopedObject(logs[lid].fact_ids)).filter(([fid])=>e.factKnown(fid,facts[fid])).map(([fid])=>scopedText(facts[fid].claim))].some(text=>text.includes(title)));return{id,title:known?title:''};});
 const remote=Object.entries(scopedObject(s.phone?.messages)).filter(([,m])=>m.state==='sent'&&m.sender!=='player'&&m.sender!==e.own&&e.named(m.sender)&&e.playerValue(m.participants_at_send)===true&&m.participants_at_send?.[m.sender]===true&&e.playerValue(m.recipients)===true&&scopedDate(m.date)&&scopedTime(m.time)&&m.date===world.current_date&&m.date+' '+m.time<=e.now&&!!scopedText(m.body,1600)&&Object.keys(scopedObject(m.source_log_ids)).some(id=>e.logKnown(logs[id])&&logs[id].source_message_id.startsWith('phone:'))).sort(([a,x],[b,y])=>(y.date+' '+y.time).localeCompare(x.date+' '+x.time)||a.localeCompare(b)).slice(0,1).map(([,m])=>({sender:e.displayName(m.sender),time:m.time,body:scopedText(m.body,240)}));
