 return{ready:e.ready,date:e.ready?world.current_date:'',time:e.ready?world.current_time:'',location:e.ready?e.location:'',control:e.control,identity_kind:scopedText(s.player?.identity?.kind,40),onsite:onsite.map(name=>({display_name:e.displayName(name)})),heard:heard.map(name=>({display_name:e.displayName(name)})),appointments:e.ready?appointments:[],events:e.ready?knownEvents:[],facts:e.ready?knownFacts:[],remote:e.ready?remote:[],clubs};
