function scopedMention(text,candidates){
 let chosen=null;const request=typeof text==='string'?text.slice(-4000):'';
 for(const item of candidates)for(const alias of item.aliases){
  if(!alias)continue;let index=request.lastIndexOf(alias);if(index<0)continue;
  if(alias.length===1&&(!/^[\s\uff0c\u3002\uff1b\uff1a\u3001\uff01\uff1f\u201c\u300c\uff08(]?$/.test(request[index-1]??'')||!/^[\s\uff0c\u3002\uff1b\uff1a\u3001\uff01\uff1f\u201d\u300d\uff09)]?$/.test(request[index+1]??'')))continue;
  if(!chosen||index>chosen.index||index===chosen.index&&alias.length>chosen.length)chosen={item,index,length:alias.length};
 }
 return chosen?.item??null;
}

function scopedPublicCandidate(e,catalog,selected){
 if(!e.ready||selected.length>=5||selected.filter(p=>['see','hear'].includes(p.mode)).length>=3)return selected;
 const minutes=Number(e.world.current_time.slice(0,2))*60+Number(e.world.current_time.slice(3));
 if(!(minutes>=740&&minutes<790||minutes>=930&&minutes<=1050))return selected;
