 const summer=Object.values(scopedObject(e.s.school?.public_calendar)).some(x=>x?.event_id==='summer_break'&&scopedDate(x.date)&&!!scopedText(x.announcement_source)&&x.state!=='\u5df2\u53d6\u6d88'&&e.world.current_date>=x.date);
