 if(claims.some(claim=>empty.test(claim)))return selected;
 for(const hint of catalog.publicCandidates?.[e.location]??[]){
  if(hint.location!==e.location||catalog.canonicalActors[hint.id]!==hint.name||catalog.characters[hint.name]?.id!==hint.id)continue;
  if(hint.name===e.own||selected.some(p=>p.name===hint.name))continue;
  if(['retained_005','kanoe_yuuko'].includes(hint.id))continue;
  if(e.characters[hint.name]&&e.characters[hint.name].registry_id!==hint.id)continue;
  const absent=new RegExp('^'+literal(hint.name)+'(?:\u76ee\u524d|\u73b0\u5728|\u6b64\u523b|\u5f53\u4e0b)?(?:\u4e0d\u5728'+place+'|(?:\u5df2|\u5df2\u7ecf|\u521a\u521a)?\u79bb\u5f00'+place+')');
  if(claims.some(claim=>absent.test(claim)))continue;
  // Undated present/location caches may describe an earlier visit, not today's absence.
  return [...selected,{name:hint.name,mode:'candidate',known:e.characters[hint.name]?.known===true}];
