 if(['\u8fdb\u884c\u4e2d','\u6682\u505c'].includes(priorHook?.state)&&Object.keys(scopedObject(priorHook.source_log_ids)).some(id=>e.logKnown(e.logs[id])&&e.logs[id].event_id==='story_H29'))return selected;
