function selectScopedCharacters(input,catalog,lastUserMessage=''){
 const e=scopedEvidence(input,catalog),selected=[];
 if(e.own&&catalog.characters[e.own])selected.push({name:e.own,mode:'player',known:true});
 const onsite=Object.keys(e.characters).filter(name=>catalog.characters[name]&&e.characters[name].registry_id===catalog.characters[name].id&&e.atSite(name)&&(e.capability(name,'see')||e.capability(name,'hear'))).sort((a,b)=>Number(e.capability(b,'see'))-Number(e.capability(a,'see'))||a.localeCompare(b,'zh-CN')).slice(0,3);
 for(const name of onsite)selected.push({name,mode:e.capability(name,'see')?'see':'hear',known:e.characters[name].known===true});
 const candidates=Object.entries(catalog.characters).filter(([name])=>!(name==='\u6a31\u5c9b\u9ebb\u8863'&&e.maiForgotten)).map(([name,record])=>({name,aliases:[...record.aliases,...(e.named(name)?[scopedText(e.characters[name].display_name,40)]:[])]}));
 const mentioned=scopedMention(lastUserMessage,candidates);
 if(mentioned&&!selected.some(row=>row.name===mentioned.name))selected.push({name:mentioned.name,mode:'mentioned',known:e.characters[mentioned.name]?.known===true});
 return scopedMaiFirstCandidate(e,catalog,scopedPublicCandidate(e,catalog,selected.slice(0,5)));
}

function selectScopedEnvironment(input,catalog,lastUserMessage='',people=[]){
 const e=scopedEvidence(input,catalog);if(!e.ready)return{locations:[],clubs:[]};
 const locations=catalog.locations.filter(row=>row.keys.includes(e.location)||row.classrooms&&/^\u9ad8[\u4e00\u4e8c\u4e09].*\u73ed$/.test(e.location)||row.homes&&/\u4f4f\u5904|\u5bb6$|\u516c\u5bd3|\u5367\u5ba4|\u5bbf\u820d/.test(e.location)).slice(0,1);
 const mentioned=scopedMention(lastUserMessage,catalog.clubs.map(row=>({...row,aliases:row.aliases})));
 const byLocation=catalog.clubs.filter(row=>row.locations.includes(e.location)).sort((a,b)=>Number(b.people.some(name=>people.some(p=>p.name===name)))-Number(a.people.some(name=>people.some(p=>p.name===name)))||a.order-b.order).slice(0,2);
