   lines.push('<\u4eba\u7269\u8d44\u6599 \u5bf9\u8c61="'+scopedEscape(person.name)+'" registry_id="'+scopedEscape(catalog.characters[person.name].id)+'" \u7528\u9014="'+mode+'" \u5df2\u76f8\u8bc6="'+person.known+'">');
   for(const title of catalog.characters[person.name].titles){const literal=title.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const content=await helpers.getwi(catalog.book,new RegExp('^'+literal+'(?![\\s\\S])'));if(typeof content!=='string'||!content.trim())throw Error('\u4eba\u7269\u8d44\u6599\u8bfb\u53d6\u4e3a\u7a7a\uff1a'+title);lines.push(content);}
   lines.push('</\u4eba\u7269\u8d44\u6599>');
   const material=catalog.authorScenes?.[person.material];
