function projectStoryVariables(input,context,catalog) {
  const e=storyEvidence(input,catalog);if(!e.ready)return '<status_current_variable>\u5f53\u524d\u65f6\u95f4\u6216\u5730\u70b9\u5c1a\u672a\u786e\u7acb\uff0c\u63a5\u7eed\u5f00\u573a\u4e0e\u73a9\u5bb6\u8f93\u5165\u3002</status_current_variable>';
