    if(value===null || typeof value==='boolean' || typeof value==='number')return value;
    if(Array.isArray(value))return value.slice(0,4).map(v=>compact(v,limit));
    return Object.fromEntries(Object.entries(storyObject(value)).slice(0,10).map(([k,v])=>[storyText(k,80),compact(v,limit)]));
