  const facts=Object.fromEntries(factIds.map(([id,f])=>[id,{claim:storyText(f.claim,100),truth_status:f.truth_status,source_log_id:f.source_log_id}]));
  const perception={};
  const perceptionTargets=[...(context.onsite??[])];
  if(context.hookId==='H20'){
