    if(ghost?.present===true && storyLocation(ghost.location)===context.location && !!storyText(ghost.location_basis) && Object.values(storyObject(e.s.knowledge?.perception?.['\u5e9a\u5915\u5b50'])).some(p=>Object.keys(storyObject(p?.source_fact_ids)).some(id=>e.knownFact(id,e.facts[id]))))perceptionTargets.unshift('\u5e9a\u5915\u5b50');
  }
  if(context.mai)perceptionTargets.unshift('\u6a31\u5c9b\u9ebb\u8863');
  for(const target of [...new Set(perceptionTargets)].slice(0,3)){
    for(const observer of ['player',...(context.onsite??[]).filter(n=>n!==target)].slice(0,3)){
      const records=e.s.knowledge?.perception?.[target],p=observer==='player'?e.playerValue(records):records?.[observer];if(!p || !storyText(p.basis) || !storyDate(p.established_date) || p.established_date>e.world.current_date)continue;
      const sources=Object.keys(storyObject(p.source_fact_ids));
