      if(!sources.every(id=>e.knownFact(id,e.facts[id])))continue;
      (perception[target]??={})[observer]={see:p.see===true,hear:p.hear===true,basis:storyText(p.basis,50),established_date:p.established_date};
    }
  }
  const calendar=Object.entries(storyObject(e.s.school?.public_calendar)).filter(([,x])=>!!storyText(x.announcement_source) && ['summer_open_day','summer_break'].includes(x.event_id)).slice(0,3);
  const public_calendar=Object.fromEntries(calendar.map(([id,x])=>[id,compact({title:x.title,date:x.date,time:x.time,location:x.location,state:x.state,event_id:x.event_id,announcement_source:x.announcement_source},60)]));
