  const view={statistics,world:compact(e.world,80),school:{public_calendar},player:{control:e.control,identity:compact(e.s.player?.identity,60),cash:e.s.player?.cash??null,club_memberships:compact(e.s.player?.club_memberships,40),goals:compact(e.s.player?.goals,60),carried_items:compact(e.s.player?.carried_items,40)},characters,events,event_log,knowledge:{facts,perception}};
