  let out=wrap(view);
  // Remove optional detail in priority order; never truncate serialized JSON.
  for(const remove of [...statisticsIds.filter(id=>id!==selfStatisticsId).reverse().map(id=>()=>{delete view.statistics[id];}),()=>{delete view.knowledge.facts;},()=>{delete view.event_log;},()=>{view.player.carried_items={};view.player.goals={};},...names.slice().reverse().map(name=>()=>{delete view.characters[name].outfit;}),...names.slice().reverse().map(name=>()=>{delete view.characters[name];}),()=>{view.events={};},()=>{view.player={control:e.control,cash:view.player.cash};},()=>{delete view.knowledge;}]){
